def add_numbers(a: int, b: int) -> int:
    """2つの数値を足し算する関数"""
    result = a + b
    return result

def binary_search(arr: list, target: int) -> int:
    """配列内で要素を二分探索する"""
    left = 0
    right = len(arr) - 1

    while left <= right:
        mid = (left + right) // 2
        if arr[mid] == target:
            return mid
        elif arr[mid] < target:
            left = mid + 1
        else:
            right = mid - 1

    return -1

if __name__ == "__main__":
    nums = [1, 2, 3, 4, 5]
    print(add_numbers(10, 20))
    result = binary_search(nums, 4)
    print(f"Found at index: {result}")
